mapper.select:
SELECT CAPS.*, nvl(PCD.CASH_PRINCIPAL,0) CASH_PRINCIPAL, nvl(PCD.CASH_INTEREST,0) CASH_INTEREST FROM CT_ABS_PRODUCT_STRUCTURE CAPS LEFT JOIN (SELECT CD.STRUCTURE_ID, SUM(PLAN_CASH_PRINCIPAL) CASH_PRINCIPAL, SUM(PLAN_CASH_INTEREST) CASH_INTEREST FROM CT_ABS_PRODUCT_CASH_DETAIL CD JOIN CT_ABS_PRODUCT_COLLECTION PC ON CD.COLLECTION_ID=PC.COLLECTION_ID WHERE 1=1
AND PC.DATA_CLASS = #{dataClass}
AND PC.TIMES < #{times}
GROUP BY CD.STRUCTURE_ID) PCD ON PCD.STRUCTURE_ID=CAPS.STRUCTURE_ID WHERE CAPS.STRUCTURE_ID=#{structureId}
